  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une cellule de racine d’oignon en pleine division","competence":"observer-schema","situation":"Au microscope, Chloé observe le bout d’une racine d’oignon. Elle repère une cellule dont les chromosomes sont tous rangés au milieu, et elle la schématise.","documents":[{"id":"cellule","type":"schema","titre":"Une cellule de racine d’oignon","largeur":340,"hauteur":240,"elements":[{"forme":"ellipse","cx":170,"cy":120,"rx":140,"ry":92,"teinte":"vert","motif":"clair"},{"forme":"ligne","de":[58,120],"a":[170,64],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[282,120],"a":[170,64],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[58,120],"a":[170,102],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[282,120],"a":[170,102],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[58,120],"a":[170,140],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[282,120],"a":[170,140],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[58,120],"a":[170,178],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[282,120],"a":[170,178],"style":"pointilles","teinte":"gris"},{"forme":"polygone","points":[[159,52],[164,52],[170,61],[176,52],[181,52],[174,64],[181,76],[176,76],[170,67],[164,76],[159,76],[166,64]],"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"polygone","points":[[159,90],[164,90],[170,99],[176,90],[181,90],[174,102],[181,114],[176,114],[170,105],[164,114],[159,114],[166,102]],"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"polygone","points":[[159,128],[164,128],[170,137],[176,128],[181,128],[174,140],[181,152],[176,152],[170,143],[164,152],[159,152],[166,140]],"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"polygone","points":[[159,166],[164,166],[170,175],[176,166],[181,166],[174,178],[181,190],[176,190],[170,181],[164,190],[159,190],[166,178]],"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":58,"cy":120,"r":7,"teinte":"ambre","motif":"plein"},{"forme":"cercle","cx":282,"cy":120,"r":7,"teinte":"ambre","motif":"plein"},{"forme":"etiquette","x":40,"y":24,"texte":"Fibres du fuseau","vers":[100,98]},{"forme":"etiquette","x":300,"y":24,"texte":"Pôle de la cellule","vers":[284,114]},{"forme":"texte","x":170,"y":232,"texte":"Photographie schématisée, grossissement 400","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma écrit pour l’exercice"},{"id":"cycle","type":"chaine","disposition":"cycle","titre":"Le cycle cellulaire","noeuds":[{"id":"z5","texte":"G1"},{"id":"z6","texte":"S"},{"id":"z7","texte":"G2"},{"id":"z8","texte":"Mitose"}],"liens":[{"de":"z5","a":"z6"},{"de":"z6","a":"z7"},{"de":"z7","a":"z8"},{"de":"z8","a":"z5"}]}],"questions":[{"enonce":"Touche tous les chromosomes de cette cellule.","aide":"Cherche les formes en X : chacune est un chromosome.","type":"zone","document":"cellule","multiple":true},{"enonce":"Dans quelle phase de la mitose se trouve cette cellule ?","aide":"Regarde où sont placés les chromosomes par rapport aux deux pôles.","type":"choix","options":[{"id":"a","texte":"Prophase"},{"id":"b","texte":"Métaphase"},{"id":"c","texte":"Anaphase"},{"id":"d","texte":"Télophase"}],"multiple":false},{"enonce":"Combien de chromatides compte cette cellule au total ?","aide":"Chaque chromosome en X est formé de deux chromatides.","type":"nombre"},{"enonce":"Au cours de quelle phase du cycle l’ADN de cette cellule a-t-il été copié, avant la mitose ?","aide":"Cherche la phase de l’interphase où l’ADN est répliqué.","type":"zone","document":"cycle","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z3","z4"]},"explication":"La cellule compte **4 chromosomes**, chacun en forme de X : deux chromatides jointes par le centromère."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les chromosomes alignés à l’équateur de la cellule, attachés aux fibres du fuseau : c’est la **métaphase**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"4 chromosomes × 2 chromatides = **8 chromatides**. Elles se sépareront en anaphase."},{"cle":{"type":"zone","ids":["z6"]},"explication":"C’est la **phase S** (synthèse) : chaque chromosome passe d’une à deux chromatides, ce qui explique les X vus en métaphase."}]$ex$::jsonb),
  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien de temps dure une métaphase ?","competence":"lire-graphique","situation":"Pour comprendre comment une cellule de racine copie puis répartit son ADN, Samir mesure la quantité d’ADN au cours du cycle, puis compte les cellules de chaque stade sur une lame.","documents":[{"id":"adn","type":"graphique","forme":"courbe","titre":"Quantité d’ADN d’une cellule au cours du cycle","categories":["G1","S (début)","S (milieu)","S (fin)","G2","Prophase","Métaphase","Anaphase","Télophase","Cellule fille"],"series":[{"nom":"Quantité d’ADN","valeurs":[2,2.5,3,4,4,4,4,4,4,2],"teinte":"violet"}],"axeY":{"titre":"Quantité d’ADN par cellule","unite":"unités arbitraires","min":0,"max":5,"pas":1},"axeX":{"titre":"Étape du cycle"},"valeurs":false,"source":"Valeurs simplifiées pour l’exercice"},{"id":"comptage","type":"tableau","titre":"Comptage de 400 cellules du méristème de racine","colonnes":["Stade observé","Nombre de cellules"],"lignes":[["Interphase",340],["Prophase",30],["Métaphase",10],["Anaphase",8],["Télophase",12]],"enteteLignes":true,"source":"Comptage écrit pour l’exercice"}],"questions":[{"enonce":"Touche le stade où la quantité d’ADN atteint pour la première fois sa valeur maximale.","aide":"Suis la courbe depuis G1 : elle monte pendant la phase S.","type":"zone","document":"adn","multiple":false},{"enonce":"Par combien la quantité d’ADN est-elle multipliée entre G1 et G2 ?","aide":"Lis la valeur en G1 puis celle en G2 et divise.","type":"nombre"},{"enonce":"Que montre la comparaison entre G1 et la cellule fille à la fin du cycle ?","aide":"Compare la dernière valeur de la courbe à la toute première.","type":"choix","options":[{"id":"a","texte":"Les cellules filles ont la même quantité d’ADN que la cellule mère avant réplication"},{"id":"b","texte":"Les cellules filles ont deux fois plus d’ADN que la cellule mère en G1"},{"id":"c","texte":"Les cellules filles ont deux fois moins d’ADN que la cellule mère en G1"},{"id":"d","texte":"La quantité d’ADN change au hasard à chaque cycle"}],"multiple":false},{"enonce":"Le cycle de ces cellules dure 24 h, soit 1 440 min. Calcule la durée moyenne de la métaphase, en minutes.","aide":"La part de cellules en métaphase est proportionnelle à la durée de cette phase : divise 10 par 400, puis multiplie par 1 440.","type":"nombre","unite":"min"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"La quantité d’ADN atteint 4 unités **à la fin de la phase S** : la réplication est alors terminée."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"4 ÷ 2 = **2** : la réplication double la quantité d’ADN, sans changer le nombre de chromosomes."},{"cle":{"type":"choix","ids":["a"]},"explication":"La courbe revient à **2 unités** : la mitose donne deux cellules filles identiques à la cellule mère, avec la même quantité d’ADN."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 min","explication":"10 ÷ 400 = 0,025 ; 0,025 × 1 440 = **36 min**. Plus un stade est long, plus on y trouve de cellules sur la lame."}]$ex$::jsonb),
  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux frères, mêmes parents, pas les mêmes gènes","competence":"raisonner","situation":"Léo et Malik ont les mêmes parents, mais ne sont pas jumeaux. Leur professeure de SVT leur demande de comprendre, courbe et tableau en main, d’où vient cette différence.","documents":[{"id":"meiose","type":"graphique","forme":"courbe","titre":"Quantité d’ADN par cellule au cours de la méiose","categories":["G1","Fin de S","Prophase I","Anaphase I","Fin de méiose I","Anaphase II","Gamètes"],"series":[{"nom":"Quantité d’ADN","valeurs":[2,4,4,4,2,2,1],"teinte":"corail"}],"axeY":{"titre":"Quantité d’ADN par cellule","unite":"unités arbitraires","min":0,"max":5,"pas":1},"axeX":{"titre":"Étape"},"valeurs":false,"source":"Valeurs simplifiées pour l’exercice"},{"id":"especes","type":"tableau","titre":"Brassage interchromosomique seul","colonnes":["Espèce","Chromosomes (2n)","Paires d’homologues (n)","Gamètes différents possibles (2 puissance n)"],"lignes":[["Drosophile",8,4,16],["Pois",14,7,"?"],["Humain",46,23,"8 388 608"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le stade où la quantité d’ADN par cellule est, pour la première fois, divisée par deux après la réplication.","aide":"Cherche la première baisse de la courbe, après le palier à 4.","type":"zone","document":"meiose","multiple":false},{"enonce":"Combien de fois la quantité d’ADN d’un gamète est-elle plus petite que celle de la cellule à la fin de la phase S ?","aide":"Compare la valeur « Fin de S » à la valeur « Gamètes ».","type":"nombre"},{"enonce":"Range ces événements dans l’ordre où ils se produisent.","aide":"La phase S précède toute division ; la méiose II ressemble à une mitose.","type":"ordre","items":[{"id":"a","texte":"Réplication de l’ADN (phase S)"},{"id":"b","texte":"Crossing-over en prophase I"},{"id":"c","texte":"Quatre cellules haploïdes"},{"id":"d","texte":"Séparation des chromatides (anaphase II)"},{"id":"e","texte":"Séparation des chromosomes homologues (anaphase I)"}]},{"enonce":"Chez le pois (2n = 14), combien de gamètes différents le seul brassage interchromosomique peut-il produire ?","aide":"Cherche d’abord n, puis calcule 2 multiplié n fois par lui-même.","type":"nombre"},{"enonce":"Quelle explication rend le mieux compte de la différence génétique entre Léo et Malik ?","aide":"Pense à ce qui produit les gamètes et à ce qui les réunit.","type":"choix","options":[{"id":"a","texte":"Leurs cellules se sont divisées par mitose, qui crée beaucoup de diversité génétique"},{"id":"b","texte":"Chaque gamète est unique (brassages de la méiose) et la fécondation les associe au hasard"},{"id":"c","texte":"La réplication de l’ADN a donné à chacun des gènes différents de ceux des parents"},{"id":"d","texte":"Chacun a reçu l’ADN d’un seul des deux parents, à moitié chacun"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"La quantité passe de 4 à 2 **à la fin de la méiose I** : les chromosomes homologues sont répartis dans deux cellules."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"4 ÷ 1 = **4** : un gamète porte la moitié des chromosomes (n) de la cellule de départ, chacun à une seule chromatide."},{"cle":{"type":"ordre","ids":["a","b","e","d","c"]},"explication":"S, puis le crossing-over (**prophase I**), la séparation des **homologues** (anaphase I), celle des **chromatides** (anaphase II), enfin quatre cellules haploïdes."},{"cle":{"type":"nombre","valeur":128,"tolerance":0},"affichage":"128","explication":"n = 7 paires d’homologues ; 2⁷ = 2 × 2 × 2 × 2 × 2 × 2 × 2 = **128** gamètes possibles."},{"cle":{"type":"choix","ids":["b"]},"explication":"La **méiose** produit des gamètes tous différents (brassages inter et intrachromosomique), et la **fécondation** associe deux d’entre eux au hasard."}]$ex$::jsonb),
  ('de8ed94b-796f-5073-b843-116097058972'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une bulle qui s’ouvre dans l’ADN","competence":"observer-schema","situation":"Avant de se diviser, une cellule copie son ADN. Au microscope électronique, on voit la molécule s’ouvrir en une « bulle » : le schéma de Nina en donne le principe.","documents":[{"id":"oeil","type":"schema","titre":"Une molécule d’ADN pendant la réplication","largeur":340,"hauteur":230,"elements":[{"forme":"ligne","de":[20,104],"a":[100,104],"teinte":"brun","epaisseur":2},{"forme":"ligne","de":[20,126],"a":[100,126],"teinte":"brun","epaisseur":2},{"forme":"ligne","de":[240,104],"a":[320,104],"teinte":"brun","epaisseur":2},{"forme":"ligne","de":[240,126],"a":[320,126],"teinte":"brun","epaisseur":2},{"forme":"ligne","de":[32,108],"a":[32,122],"teinte":"gris"},{"forme":"ligne","de":[54,108],"a":[54,122],"teinte":"gris"},{"forme":"ligne","de":[76,108],"a":[76,122],"teinte":"gris"},{"forme":"ligne","de":[98,108],"a":[98,122],"teinte":"gris"},{"forme":"ligne","de":[262,108],"a":[262,122],"teinte":"gris"},{"forme":"ligne","de":[284,108],"a":[284,122],"teinte":"gris"},{"forme":"ligne","de":[306,108],"a":[306,122],"teinte":"gris"},{"forme":"chemin","d":"M100,104 C125,34 215,34 240,104","teinte":"brun"},{"forme":"chemin","d":"M100,126 C125,196 215,196 240,126","teinte":"brun"},{"forme":"chemin","d":"M118,100 C138,62 202,62 222,100","teinte":"violet"},{"forme":"chemin","d":"M118,130 C138,168 202,168 222,130","teinte":"violet"},{"forme":"cercle","cx":100,"cy":115,"r":13,"teinte":"jaune","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":240,"cy":115,"r":13,"teinte":"jaune","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":170,"y":118,"texte":"Œil de réplication","taille":"petit","ancre":"milieu","italique":true},{"forme":"etiquette","x":52,"y":40,"texte":"Brin parental","vers":[50,104]},{"forme":"etiquette","x":170,"y":215,"texte":"Brin néoformé","vers":[170,159]},{"forme":"texte","x":60,"y":150,"texte":"ADN non encore copié","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma simplifié écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux fourches de réplication, là où la double hélice s’ouvre.","aide":"Les fourches sont aux deux extrémités de la bulle, là où les brins se séparent.","type":"zone","document":"oeil","multiple":true},{"enonce":"Combien de molécules d’ADN à double brin y aura-t-il à la fin de la copie de cette région ?","aide":"Chaque brin parental s’associe à un brin néoformé.","type":"nombre"},{"enonce":"Que contient chaque molécule fille ?","aide":"Regarde, en un point de la bulle, ce qui est associé à chaque brin brun.","type":"choix","options":[{"id":"a","texte":"Un brin parental et un brin néoformé"},{"id":"b","texte":"Deux brins parentaux"},{"id":"c","texte":"Deux brins néoformés"},{"id":"d","texte":"Des fragments parentaux et néoformés mêlés"}],"multiple":false},{"enonce":"Relie chaque élément à son rôle.","aide":"Une enzyme ouvre, l’autre construit.","type":"association","gauche":[{"id":"g0","texte":"ADN hélicase"},{"id":"g1","texte":"ADN polymérase"},{"id":"g2","texte":"Œil de réplication"}],"droite":[{"id":"d0","texte":"Bulle bordée de deux fourches"},{"id":"d1","texte":"Construit le brin complémentaire"},{"id":"d2","texte":"Ouvre la double hélice"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"Les **deux fourches** bordent l’œil de réplication. L’ADN hélicase y ouvre la double hélice, et la bulle grandit des deux côtés."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Chaque brin parental sert de modèle à un brin neuf : on obtient **2 molécules** filles, identiques à la molécule de départ."},{"cle":{"type":"choix","ids":["a"]},"explication":"La réplication est **semi-conservative** : un brin ancien est conservé, un brin neuf est construit contre lui."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"L’**hélicase** ouvre, la **polymérase** construit en respectant A–T et C–G, et l’**œil** est la bulle bordée de deux fourches."}]$ex$::jsonb),
  ('de8ed94b-796f-5073-b843-116097058972'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les tubes de Meselson et Stahl","competence":"experimenter","situation":"En 1958, deux chercheurs américains ont voulu savoir comment l’ADN se copie. Voici leur expérience et ses résultats, que tu vas interpréter comme eux.","documents":[{"id":"proto","type":"texte","genre":"article","titre":"Le protocole","blocs":["Des bactéries *Escherichia coli* sont cultivées pendant plusieurs générations dans un milieu dont l’azote est lourd (15N) : tout leur ADN devient « lourd ».","On les transfère dans un milieu à azote léger (14N). À chaque génération, on prélève des bactéries, on extrait leur ADN et on le centrifuge à grande vitesse dans du chlorure de césium.","Les molécules se rangent selon leur densité : une molécule lourde forme une bande en bas du tube, une légère une bande en haut, une molécule mixte une bande au milieu."],"source":"Texte écrit pour l’exercice, d’après l’expérience de Meselson et Stahl (1958)"},{"id":"bandes","type":"tableau","titre":"Les bandes observées dans le tube","colonnes":["Prélèvement","Bande légère (%)","Bande intermédiaire (%)","Bande lourde (%)"],"lignes":[["Départ (milieu 15N)",0,0,100],["Après 1 génération en 14N",0,100,0],["Après 2 générations en 14N",50,50,0]],"enteteLignes":true,"source":"Résultats simplifiés"}],"questions":[{"enonce":"Quel pourcentage de l’ADN est intermédiaire après deux générations en milieu léger ?","aide":"Lis la dernière ligne du tableau, colonne « intermédiaire ».","type":"nombre","unite":"%"},{"enonce":"Après une génération, une seule bande, intermédiaire, apparaît. Quelle hypothèse ce résultat écarte-t-il ?","aide":"L’hypothèse conservative prévoit une molécule entièrement ancienne et une entièrement neuve.","type":"choix","options":[{"id":"a","texte":"L’hypothèse conservative"},{"id":"b","texte":"L’hypothèse semi-conservative"},{"id":"c","texte":"Aucune : toutes les hypothèses restent possibles"},{"id":"d","texte":"La réplication elle-même"}],"multiple":false},{"enonce":"Après deux générations, on observe deux bandes distinctes. Quelle hypothèse ce résultat écarte-t-il, en plus de la précédente ?","aide":"Dans l’hypothèse dispersive, anciens et nouveaux fragments restent mêlés dans chaque molécule.","type":"choix","options":[{"id":"a","texte":"L’hypothèse dispersive"},{"id":"b","texte":"L’hypothèse semi-conservative"},{"id":"c","texte":"Aucune des deux"},{"id":"d","texte":"L’existence de la bande intermédiaire"}],"multiple":false},{"enonce":"D’après le modèle semi-conservatif, quel pourcentage des molécules contiendrait encore un brin lourd après trois générations en milieu léger ?","aide":"Compte les molécules à chaque génération : 1, 2, 4, 8. Combien d’entre elles possèdent un brin issu du départ ?","type":"nombre","unite":"%"}]}$ex$::jsonb,
