te":"gris","motif":"clair"},{"forme":"ligne","de":[45,74],"a":[45,120],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[91,74],"a":[91,120],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[137,74],"a":[137,120],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[183,74],"a":[183,120],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[229,74],"a":[229,120],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[275,74],"a":[275,120],"teinte":"gris","style":"pointilles"},{"forme":"rect","x":150,"y":50,"l":22,"h":12,"teinte":"corail","motif":"plein"},{"forme":"emoji","x":300,"y":22,"emoji":"☀️","taille":28},{"forme":"ligne","de":[286,30],"a":[190,46],"fleche":"fin","teinte":"corail"},{"forme":"texte","x":160,"y":188,"texte":"Brin du haut : lu de gauche à droite","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Par quel nombre la fidélité de la copie est-elle multipliée entre « polymérase seule » et le système complet ?","aide":"Divise 1 milliard par 100 000 : combien de zéros de plus ?","type":"nombre"},{"enonce":"Touche les deux bases que les rayons UV ont soudées entre elles.","aide":"Cherche le petit pont dessiné entre deux bases voisines du même brin.","type":"zone","document":"uv","multiple":true},{"enonce":"La cellule se divise avant d’avoir réparé cette lésion. Que peut-il arriver ?","aide":"Que devient une erreur qui subsiste après la réplication ?","type":"choix","options":[{"id":"a","texte":"Les UV disparaissent de la cellule à la division"},{"id":"b","texte":"Une erreur de copie, donc une mutation transmise aux filles"},{"id":"c","texte":"La cellule fabrique un brin d’ADN supplémentaire"},{"id":"d","texte":"Rien, car l’ADN est toujours copié sans aucune erreur"}],"multiple":false},{"enonce":"Avec le système complet, combien d’erreurs restent en moyenne après la copie de 5 milliards de nucléotides ?","aide":"Une erreur pour un milliard de nucléotides : combien de milliards ici ?","type":"nombre"},{"enonce":"Associe chaque agent mutagène à son effet sur l’ADN.","aide":"Les UV agissent sur deux bases côte à côte ; les radiations ionisantes sont très énergétiques.","type":"association","gauche":[{"id":"g0","texte":"Rayons UV"},{"id":"g1","texte":"Radiations ionisantes"},{"id":"g2","texte":"Benzène, goudrons du tabac"}],"droite":[{"id":"d0","texte":"Endommagent les bases ou gênent la réplication"},{"id":"d1","texte":"Cassent les brins"},{"id":"d2","texte":"Soudent deux bases voisines"}]}]}$ex$::jsonb,
