talique":true}],"source":"Arbre imaginé pour l’exercice"}],"questions":[{"enonce":"Touche toutes les personnes de l’arbre de qui Yanis tient son ADN mitochondrial.","aide":"L’ADN mitochondrial se transmet uniquement par la mère : remonte la lignée des mères.","type":"zone","document":"arbre","multiple":true},{"enonce":"Touche toutes les personnes de l’arbre de qui Yanis tient son chromosome Y.","aide":"Le chromosome Y passe de père en fils : remonte la lignée des pères.","type":"zone","document":"arbre","multiple":true},{"enonce":"Inès hérite-t-elle du chromosome Y de son père ?","aide":"Qui, parmi les enfants de Samir, possède un chromosome Y ?","type":"choix","options":[{"id":"a","texte":"Non : le chromosome Y passe de père en fils"},{"id":"b","texte":"Oui, mais seulement la moitié"},{"id":"c","texte":"Non, mais elle le reçoit de sa mère"},{"id":"d","texte":"Oui : tous les enfants le reçoivent"}],"multiple":false},{"enonce":"Quel marqueur permettrait de retrouver la lignée maternelle commune à Yanis et Inès ?","aide":"Un seul des deux marqueurs se transmet par la mère, aux filles comme aux fils.","type":"choix","options":[{"id":"a","texte":"L’ADN mitochondrial"},{"id":"b","texte":"Le chromosome Y"},{"id":"c","texte":"Aucun marqueur génétique"},{"id":"d","texte":"Le chromosome Y de leur mère"}],"multiple":false}]}$ex$::jsonb,
