  ('dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dater une séparation grâce aux mutations","competence":"modeliser","situation":"Trois populations d’une même espèce vivent aujourd’hui sur des îles différentes. Pour savoir depuis quand elles sont séparées, des chercheurs comptent les différences de leur ADN.","documents":[{"id":"regle","type":"texte","genre":"consigne","titre":"Le principe de l’horloge moléculaire","blocs":["Des généticiens comparent un fragment de 10 000 nucléotides d’ADN mitochondrial chez trois populations A, B et C.","On suppose que les mutations s’accumulent à un rythme constant : entre deux lignées séparées, on compte une différence de plus tous les 10 000 ans."],"source":"Texte écrit pour l’exercice (populations fictives)"},{"id":"diff","type":"graphique","forme":"barres","titre":"Différences observées entre deux populations","categories":["A et B","A et C","B et C"],"series":[{"nom":"Différences","valeurs":[8,22,20],"teinte":"violet"}],"axeY":{"titre":"Nombre de différences","unite":"sur 10 000 nucléotides","min":0,"max":25,"pas":5},"axeX":{"titre":"Paire de populations"},"valeurs":false,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la paire de populations dont les lignées se sont séparées le plus tôt.","aide":"Plus deux populations sont différentes, plus elles se sont séparées tôt.","type":"zone","document":"diff","multiple":false},{"enonce":"Depuis combien d’années les populations A et B sont-elles séparées ?","aide":"Une différence = 10 000 ans ; lis le nombre de différences entre A et B.","type":"nombre","unite":"ans"},{"enonce":"Depuis combien d’années les populations B et C sont-elles séparées ?","aide":"Même méthode : nombre de différences × 10 000 ans.","type":"nombre","unite":"ans"},{"enonce":"Que peut-on conclure sur la parenté entre les trois populations ?","aide":"Compare la date de séparation de A et B avec celle de B et C.","type":"choix","options":[{"id":"a","texte":"Les trois populations se sont toutes séparées en même temps"},{"id":"b","texte":"A et B se sont séparées avant qu’elles ne se séparent de C"},{"id":"c","texte":"A et B ont un ancêtre commun plus récent que celui de C"},{"id":"d","texte":"C est l’ancêtre direct des deux populations A et B"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"La paire **A et C** compte le plus de différences (22) : c’est elle qui a divergé le plus anciennement."},{"cle":{"type":"nombre","valeur":80000,"tolerance":0},"affichage":"80 000 ans","explication":"8 différences × 10 000 ans = **80 000 ans**."},{"cle":{"type":"nombre","valeur":200000,"tolerance":0},"affichage":"200 000 ans","explication":"20 différences × 10 000 ans = **200 000 ans**."},{"cle":{"type":"choix","ids":["c"]},"explication":"A et B (80 000 ans) sont plus proches l’une de l’autre que de C (environ 200 000 ans) : ces deux lignées **ont divergé récemment**."}]$ex$::jsonb),
  ('dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Nos génomes racontent le peuplement du monde","competence":"argumenter","situation":"Une conférencière présente trois résultats de la génétique des populations : la diversité des génomes actuels, les métissages avec d’autres humains disparus, et ce que cela dit des « races ». À toi de les interpréter.","documents":[{"id":"diversite","type":"graphique","forme":"barres","titre":"Diversité génétique de quatre populations","categories":["Afrique subsaharienne","Europe","Asie de l’Est","Océanie"],"series":[{"nom":"Différences entre deux individus","valeurs":[10,8,8,7],"teinte":"turquoise"}],"axeY":{"titre":"Différences moyennes entre deux individus","unite":"pour 10 000 nucléotides","min":0,"max":12,"pas":2},"axeX":{"titre":"Population"},"valeurs":false,"source":"Valeurs simplifiées pour l’exercice"},{"id":"metis","type":"tableau","titre":"Part du génome venue de deux populations disparues","colonnes":["Population actuelle","ADN néandertalien (%)","ADN de Denisova (%)"],"lignes":[["Afrique subsaharienne","≈ 0",0],["Europe",2,0],["Asie de l’Est",2,0.2],["Océanie",2,4]],"enteteLignes":true,"source":"Valeurs arrondies et simplifiées pour l’exercice"}],"questions":[{"enonce":"Touche la population dont les individus sont, en moyenne, les plus différents les uns des autres.","aide":"Cherche la barre la plus haute.","type":"zone","document":"diversite","multiple":false},{"enonce":"Quel argument ce graphique apporte-t-il sur l’origine d’Homo sapiens ?","aide":"La population d’origine a eu le temps d’accumuler le plus de mutations différentes.","type":"choix","options":[{"id":"a","texte":"Une origine océanienne, puisque l’Océanie est la moins diverse"},{"id":"b","texte":"Une origine européenne, puisque l’Europe est moins diverse que l’Afrique"},{"id":"c","texte":"Aucune origine géographique ne peut être déduite de ce graphique"},{"id":"d","texte":"Une origine africaine : les autres populations en sont un sous-ensemble"}],"multiple":false},{"enonce":"Un génome humain compte environ 3 milliards de paires de bases. Combien de millions de paires de bases d’origine néandertalienne un Européen en porte-t-il, selon le tableau ?","aide":"Calcule 2 % de 3 milliards (3 000 millions).","type":"nombre","unite":"millions"},{"enonce":"Touche la valeur qui montre qu’une population actuelle porte surtout de l’ADN de Denisova.","aide":"Regarde la colonne « ADN de Denisova » et cherche la valeur la plus forte.","type":"zone","document":"metis","multiple":false},{"enonce":"Complète la conclusion du programme.","aide":"Pense à l’échelle : un groupe, puis plusieurs groupes comparés.","type":"trous","segments":["La variabilité entre deux individus d’une même ",0," dépasse la variabilité moyenne entre ",1," : la notion de « race » humaine n’a aucun fondement génétique."],"banque":["population","populations","espèce","race"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"L’**Afrique subsaharienne** a la diversité la plus grande : 10 différences pour 10 000 nucléotides."},{"cle":{"type":"choix","ids":["d"]},"explication":"La diversité **maximale en Afrique** est l’argument majeur d’une origine africaine : ailleurs, on ne trouve qu’une partie de cette diversité."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 millions","explication":"2 % × 3 000 millions = 0,02 × 3 000 = **60 millions** de paires de bases."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"En **Océanie**, l’ADN de Denisova atteint environ 4 % : la trace d’un métissage avec cette population en Asie et en Océanie."},{"cle":{"type":"trous","trous":[["population"],["populations"]]},"affichage":"population · populations","explication":"La diversité **au sein d’une population** dépasse celle qui existe **entre populations** : on ne peut pas diviser l’humanité en races biologiques."}]$ex$::jsonb),
