   $ex${"titre":"La carte des altitudes du globe n’a pas une bosse mais deux","competence":"lire-graphique","situation":"En classant toutes les altitudes de la surface de la Terre, des géologues obtiennent un graphique étonnant : il n’a pas un seul sommet. Pour l’expliquer, ils datent aussi des roches de chaque côté.","documents":[{"id":"hypso","type":"graphique","forme":"barres","titre":"Répartition des altitudes à la surface du globe","categories":["−6 à −5 km","−5 à −4 km","−4 à −3 km","−3 à −2 km","−2 à −1 km","−1 à 0 km","0 à 1 km","1 à 2 km","2 à 3 km","Plus de 3 km"],"series":[{"nom":"Part de la surface","valeurs":[7,21,18,7,5,13,20,6,2,1],"teinte":"bleu"}],"axeY":{"titre":"Part de la surface du globe","unite":"%","min":0,"max":25,"pas":5},"axeX":{"titre":"Classe d’altitude"},"valeurs":false,"source":"Valeurs arrondies"},{"id":"ages","type":"tableau","titre":"Les plus vieilles roches datées","colonnes":["Croûte","Âge de la plus vieille roche (millions d’années)"],"lignes":[["Continentale","4 000"],["Océanique","200"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche les deux classes d’altitude qui occupent la plus grande part de la surface.","aide":"Cherche les deux barres les plus hautes.","type":"zone","document":"hypso","multiple":true},{"enonce":"Quelle part de la surface du globe est située sous le niveau de la mer ?","aide":"Additionne les barres dont l’altitude est négative.","type":"nombre","unite":"%"},{"enonce":"Combien de fois la plus vieille roche continentale est-elle plus âgée que la plus vieille roche océanique ?","aide":"Divise 4 000 par 200.","type":"nombre"},{"enonce":"Comment les géologues expliquent-ils que le graphique ait deux maxima ?","aide":"Chaque maximum correspond à un type de croûte.","type":"choix","options":[{"id":"a","texte":"La Terre est à demi plate, à demi creuse"},{"id":"b","texte":"Les continents sont exactement aussi hauts que les océans sont profonds"},{"id":"c","texte":"Il existe deux types de croûte, de composition et d’altitude différentes"},{"id":"d","texte":"Les altitudes ont été mesurées par deux méthodes"}],"multiple":false}]}$ex$::jsonb,
