lle","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma simplifié écrit pour l’exercice"},{"id":"uplift","type":"tableau","titre":"Soulèvement actuel de trois lieux de Scandinavie","colonnes":["Lieu","Vitesse de soulèvement (mm par an)"],"lignes":[["Nord du golfe de Botnie",9],["Stockholm",5],["Sud de la Suède",0]],"enteteLignes":true,"source":"Valeurs arrondies, ordres de grandeur"}],"questions":[{"enonce":"Touche la racine crustale de la chaîne de montagnes.","aide":"C’est la partie de la croûte qui s’enfonce dans le manteau, sous la chaîne.","type":"zone","document":"racine","multiple":false},{"enonce":"De combien de kilomètres la croûte est-elle plus épaisse sous la chaîne que sous la plaine ?","aide":"Lis les deux épaisseurs indiquées et soustrais.","type":"nombre","unite":"km"},{"enonce":"Pourquoi la Scandinavie s’élève-t-elle encore aujourd’hui ?","aide":"Pense à un iceberg dont on enlève une partie de la glace : il remonte.","type":"choix","options":[{"id":"a","texte":"La glace fondue l’a allégée : le continent flotte plus haut"},{"id":"b","texte":"Elle s’alourdit chaque année et s’enfonce dans le manteau"},{"id":"c","texte":"Le niveau de la mer baisse de 1 cm par an partout"},{"id":"d","texte":"Elle est poussée vers le haut par l’eau de la mer"}],"multiple":false},{"enonce":"En supposant un soulèvement constant de 1 cm par an, de combien de mètres un continent s’élève-t-il en 5 000 ans ?","aide":"Calcule en centimètres : 1 cm × 5 000, puis convertis en mètres.","type":"nombre","unite":"m"},{"enonce":"Touche le lieu où le soulèvement actuel est le plus rapide.","aide":"Cherche la plus grande valeur de la colonne de droite.","type":"zone","document":"uplift","multiple":false}]}$ex$::jsonb,
