  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un séisme, deux familles d’ondes, un noyau","competence":"observer-schema","situation":"Personne n’a jamais vu l’intérieur de la Terre : le forage le plus profond atteint 12 km. Pour l’explorer, les sismologues écoutent les ondes des séismes qui la traversent.","documents":[{"id":"globe","type":"schema","titre":"La structure interne de la Terre","largeur":340,"hauteur":285,"elements":[{"forme":"cercle","cx":170,"cy":120,"r":100,"teinte":"brun","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":170,"cy":120,"r":96,"teinte":"ambre","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":170,"cy":120,"r":54,"teinte":"corail","motif":"clair","id":"z3","zone":true},{"forme":"cercle","cx":170,"cy":120,"r":19,"teinte":"jaune","motif":"plein","id":"z4","zone":true},{"forme":"etiquette","x":50,"y":22,"texte":"Croûte","vers":[122,37]},{"forme":"etiquette","x":296,"y":40,"texte":"Manteau","vers":[232,72]},{"forme":"etiquette","x":52,"y":236,"texte":"Noyau externe","vers":[140,142]},{"forme":"etiquette","x":300,"y":236,"texte":"Graine","vers":[178,126]},{"forme":"ligne","de":[170,238],"a":[270,238],"teinte":"encre"},{"forme":"ligne","de":[270,233],"a":[270,243],"teinte":"encre"},{"forme":"ligne","de":[224.5,233],"a":[224.5,243],"teinte":"encre"},{"forme":"ligne","de":[190,233],"a":[190,243],"teinte":"encre"},{"forme":"ligne","de":[170,233],"a":[170,243],"teinte":"encre"},{"forme":"texte","x":270,"y":256,"texte":"0","taille":"petit","ancre":"milieu"},{"forme":"texte","x":224,"y":256,"texte":"2 900","taille":"petit","ancre":"milieu"},{"forme":"texte","x":190,"y":270,"texte":"5 100","taille":"petit","ancre":"milieu"},{"forme":"texte","x":170,"y":256,"texte":"6 371","taille":"petit","ancre":"milieu"},{"forme":"texte","x":240,"y":282,"texte":"Profondeur (km)","taille":"petit","ancre":"milieu","italique":true}],"source":"Schéma à l’échelle, épaisseur de la croûte exagérée"},{"id":"ondes","type":"tableau","titre":"Les deux familles d’ondes sismiques","colonnes":["Onde","Vitesse","Elle traverse"],"lignes":[["P (primaire)","La plus rapide","Solides et liquides"],["S (secondaire)","Plus lente","Solides uniquement"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la couche que les ondes S ne parviennent pas à traverser.","aide":"Regarde ce que traversent les ondes S, puis cherche la seule couche liquide.","type":"zone","document":"globe","multiple":false},{"enonce":"Quelle est l’épaisseur du noyau externe, entre la discontinuité de Gutenberg (2 900 km) et celle de Lehmann (5 100 km) ?","aide":"Lis les profondeurs sur l’échelle et soustrais.","type":"nombre","unite":"km"},{"enonce":"Le Moho est à 30 km sous un continent. Quelle est l’épaisseur du manteau, entre le Moho et la discontinuité de Gutenberg ?","aide":"Le manteau va du Moho (30 km) à 2 900 km de profondeur.","type":"nombre","unite":"km"},{"enonce":"Quelle onde est enregistrée en premier par une station éloignée du séisme ?","aide":"Lis la colonne « Vitesse » du tableau.","type":"choix","options":[{"id":"a","texte":"On ne peut pas savoir"},{"id":"b","texte":"L’onde P, car elle est la plus rapide"},{"id":"c","texte":"L’onde S, car elle traverse les solides"},{"id":"d","texte":"Les deux en même temps"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Les ondes S ne traversent que les solides : elles disparaissent au contact du **noyau externe**, qui est liquide."},{"cle":{"type":"nombre","valeur":2200,"tolerance":0},"affichage":"2200 km","explication":"5 100 − 2 900 = **2 200 km**."},{"cle":{"type":"nombre","valeur":2870,"tolerance":0},"affichage":"2870 km","explication":"2 900 − 30 = **2 870 km** : le manteau est la couche la plus épaisse du globe."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’onde **P** (primaire) est la plus rapide : elle arrive la première, d’où son nom."}]$ex$::jsonb),
  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Lire la vitesse des ondes jusqu’au centre de la Terre","competence":"lire-graphique","situation":"Après un séisme, le sismologue Théo rassemble deux documents : la vitesse des ondes selon la profondeur, et les enregistrements de trois stations proches de l’épicentre.","documents":[{"id":"vitesses","type":"graphique","forme":"courbe","titre":"Vitesse des ondes sismiques selon la profondeur","categories":["0","400","800","1200","1600","2000","2400","2800","3200","3600","4000","4400","4800","5200","5600","6000"],"series":[{"nom":"Onde P","valeurs":[5.8,9,11.1,12.3,12.7,13.1,13.4,13.7,8.2,8.6,9,9.4,10,11,11.2,11.3],"teinte":"violet"},{"nom":"Onde S","valeurs":[3.2,5,6.2,6.7,6.9,7.2,7.3,7.3,0,0,0,0,0,3.6,3.6,3.7],"teinte":"corail"}],"axeY":{"titre":"Vitesse des ondes","unite":"km/s","min":0,"max":14,"pas":2},"axeX":{"titre":"Profondeur","unite":"km"},"valeurs":false,"source":"Valeurs arrondies d’après un modèle de Terre de référence"},{"id":"retards","type":"tableau","titre":"Trois stations sismiques, un même séisme","colonnes":["Station","Retard de l’onde S sur l’onde P (s)"],"lignes":[["C",75],["A",25],["B",40]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la première profondeur de l’échelle où les ondes S ne sont plus enregistrées.","aide":"Suis la courbe des ondes S : à quel moment tombe-t-elle à zéro ?","type":"zone","document":"vitesses","multiple":false},{"enonce":"De combien la vitesse des ondes P baisse-t-elle entre 2 800 km et 3 200 km de profondeur ?","aide":"Lis la vitesse des P à 2 800 km, puis à 3 200 km.","type":"nombre","unite":"km/s"},{"enonce":"Près de la station B, les ondes P vont à 8 km/s et les ondes S à 4 km/s. L’onde S arrive 40 s après l’onde P. À quelle distance est le séisme ?","aide":"Si d est la distance : d ÷ 4 − d ÷ 8 = 40. Que vaut d ÷ 8 ?","type":"nombre","unite":"km"},{"enonce":"Range les stations de la plus proche à la plus éloignée du séisme.","aide":"Plus la station est loin, plus l’écart entre l’onde P et l’onde S est grand.","type":"ordre","items":[{"id":"a","texte":"Station C"},{"id":"b","texte":"Station A"},{"id":"c","texte":"Station B"}]},{"enonce":"Que signifient à la fois la disparition des ondes S et la chute de vitesse des ondes P à 2 900 km ?","aide":"Quelle famille d’ondes ne traverse pas les liquides ?","type":"choix","options":[{"id":"a","texte":"Le manteau est liquide"},{"id":"b","texte":"Le noyau externe est plus rigide que le manteau"},{"id":"c","texte":"Le noyau externe est liquide"},{"id":"d","texte":"La croûte est plus épaisse à cet endroit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k8"]},"explication":"À **3 200 km**, les ondes S disparaissent : on a franchi la discontinuité de Gutenberg (environ 2 900 km), le noyau externe est liquide."},{"cle":{"type":"nombre","valeur":5.5,"tolerance":0.2},"affichage":"5,5 km/s","explication":"13,7 − 8,2 = **5,5 km/s** : une chute brutale, qui signale le passage du manteau solide au noyau liquide."},{"cle":{"type":"nombre","valeur":320,"tolerance":0},"affichage":"320 km","explication":"Temps de l’onde S moins temps de l’onde P : d ÷ 4 − d ÷ 8 = d ÷ 8 = 40 s, donc d = 40 × 8 = **320 km**."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"Le retard croît avec la distance : A (25 s) est la plus proche, puis B (40 s), puis C (75 s)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les S ne traversent pas les liquides et les P ralentissent dans un milieu moins rigide : le **noyau externe est liquide**."}]$ex$::jsonb),
  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La zone d’ombre qui a révélé le noyau liquide","competence":"analyser-document","situation":"Au début du XXe siècle, les sismologues remarquent que certains séismes sont enregistrés partout… sauf dans une large bande autour de la Terre. Ce « trou » dans les enregistrements a tout changé.","documents":[{"id":"stations","type":"tableau","titre":"Ondes reçues selon la distance à l’épicentre","colonnes":["Distance angulaire (°)","Ondes P reçues ?","Ondes S reçues ?"],"lignes":[[20,"Oui","Oui"],[60,"Oui","Oui"],[100,"Oui","Oui"],[120,"Non","Non"],[140,"Non","Non"],[160,"Oui","Non"]],"enteteLignes":true,"source":"Enregistrements simplifiés pour l’exercice"},{"id":"frise","type":"frise","titre":"Quatre découvertes sur l’intérieur de la Terre","debut":1900,"fin":1940,"pas":5,"evenements":[{"id":"z1","date":1906,"nom":"Oldham : un noyau"},{"id":"z2","date":1909,"nom":"Mohorovičić : le Moho"},{"id":"z3","date":1913,"nom":"Gutenberg : 2 900 km"},{"id":"z4","date":1936,"nom":"Lehmann : la graine"}],"source":"Dates principales de publication"}],"questions":[{"enonce":"Dans la colonne des ondes P, touche les deux cases qui montrent la zone d’ombre.","aide":"Cherche les « Non » de la colonne des ondes P.","type":"zone","document":"stations","multiple":true},{"enonce":"La zone d’ombre des ondes P s’étend de 103° à 143° de l’épicentre. Quelle est sa largeur angulaire ?","aide":"Soustrais les deux angles.","type":"nombre","unite":"°"},{"enonce":"Les ondes S ne sont plus reçues au-delà de 103°. Qu’en déduit-on ?","aide":"Quelle propriété du milieu empêche les ondes S de passer ?","type":"choix","options":[{"id":"a","texte":"Elles sont devenues plus rapides que les ondes P"},{"id":"b","texte":"Elles sont absorbées par la croûte terrestre"},{"id":"c","texte":"Le noyau externe, liquide, les arrête"},{"id":"d","texte":"Elles se transforment en ondes P au passage"}],"multiple":false},{"enonce":"Les ondes P réapparaissent au-delà de 143°. Comment l’expliquer ?","aide":"Pense à ce qui arrive à un rayon lumineux qui change de milieu.","type":"choix","options":[{"id":"a","texte":"Elles contournent la Terre en passant par la surface"},{"id":"b","texte":"Elles traversent le noyau sans aucune déviation"},{"id":"c","texte":"Elles ont été produites par un second séisme"},{"id":"d","texte":"Le noyau les dévie (réfraction), elles émergent plus loin"}],"multiple":false},{"enonce":"Touche la découverte qui prouve que le centre du noyau est solide.","aide":"La graine est le noyau interne.","type":"zone","document":"frise","multiple":false}]}$ex$::jsonb,
