  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La cuillère qui brûle les doigts","competence":"observer-schema","situation":"Lola prépare des pâtes. Elle laisse une cuillère en métal dans la casserole, et au bout d’un moment, le bout de la cuillère devient brûlant. Que se passe-t-il dans la casserole ?","documents":[{"id":"casserole","type":"schema","titre":"Une casserole d’eau sur la plaque","largeur":340,"hauteur":240,"elements":[{"forme":"rect","x":80,"y":90,"l":160,"h":90,"teinte":"gris","motif":"clair","id":"z1"},{"forme":"rect","x":86,"y":100,"l":148,"h":74,"teinte":"bleu","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":60,"y":184,"l":200,"h":14,"teinte":"encre","motif":"plein"},{"forme":"emoji","x":170,"y":218,"emoji":"🔥","taille":30},{"forme":"ligne","de":[160,170],"a":[160,118],"fleche":"fin","teinte":"corail","epaisseur":3},{"forme":"ligne","de":[155,112],"a":[112,112],"fleche":"fin","teinte":"corail"},{"forme":"ligne","de":[165,112],"a":[208,112],"fleche":"fin","teinte":"corail"},{"forme":"ligne","de":[105,120],"a":[105,165],"fleche":"fin","teinte":"bleu"},{"forme":"ligne","de":[215,120],"a":[215,165],"fleche":"fin","teinte":"bleu"},{"forme":"ligne","de":[108,168],"a":[150,168],"fleche":"fin","teinte":"bleu"},{"forme":"ligne","de":[212,168],"a":[170,168],"fleche":"fin","teinte":"bleu"},{"forme":"polygone","points":[[222,104],[229,110],[312,28],[305,21]],"teinte":"gris","motif":"plein","id":"z3","zone":true},{"forme":"ellipse","cx":216,"cy":128,"rx":12,"ry":7,"teinte":"gris","motif":"plein"},{"forme":"emoji","x":322,"y":22,"emoji":"✋","taille":26},{"forme":"etiquette","x":290,"y":80,"texte":"Cuillère en métal","vers":[262,62]},{"forme":"etiquette","x":50,"y":60,"texte":"Eau chauffée par le bas","vers":[100,130]}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’élément où la chaleur se transmet de proche en proche, sans déplacement de matière.","aide":"Dans quel élément rien ne bouge, alors que la chaleur le parcourt ?","type":"zone","document":"casserole","multiple":false},{"enonce":"Touche l’élément où le chaud monte et le froid redescend, en boucle.","aide":"Cherche les flèches qui forment une boucle.","type":"zone","document":"casserole","multiple":false},{"enonce":"Classe chaque situation selon le mode de transfert de chaleur.","aide":"La convection a besoin de matière qui se déplace ; la conduction non.","type":"categories","categories":[{"id":"c0","texte":"Conduction"},{"id":"c1","texte":"Convection"}],"items":[{"id":"i0","texte":"Le manche de la cuillère devient chaud"},{"id":"i1","texte":"L’eau circule en boucle dans la casserole"},{"id":"i2","texte":"La chaleur traverse la lithosphère rigide"},{"id":"i3","texte":"Le manteau terrestre se déforme lentement et évacue la chaleur"}]},{"enonce":"Complète la phrase.","aide":"Un mode a besoin de matière qui circule, l’autre non.","type":"trous","segments":["La ",0," se fait de proche en proche ; la ",1," déplace de la matière."],"banque":["conduction","radiation","dérive","convection"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La chaleur remonte le long du métal **de proche en proche** : c’est la conduction."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans l’**eau**, la matière chaude monte, refroidit en surface puis redescend : c’est la convection, un transfert par déplacement de matière."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"La **conduction** domine dans la lithosphère rigide ; la **convection** dans le manteau ductile, qui flue lentement."},{"cle":{"type":"trous","trous":[["conduction"],["convection"]]},"affichage":"conduction · convection","explication":"La **conduction** transmet la chaleur de proche en proche ; la **convection** la transporte avec la matière qui se déplace."}]$ex$::jsonb),
  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi la Terre perd-elle moins de chaleur en vieillissant ?","competence":"lire-graphique","situation":"Le sol sous nos pieds est froid, mais les roches du manteau atteignent plusieurs milliers de degrés. Des géophysiciens mesurent la chaleur qui s’échappe en surface et la rapprochent de l’âge de la lithosphère océanique.","documents":[{"id":"sources","type":"tableau","titre":"D’où vient la chaleur interne de la Terre ?","colonnes":["Source","Part de la chaleur interne"],"lignes":[["Radioactivité naturelle des roches (uranium, thorium, potassium 40)","Environ 80 %"],["Chaleur résiduelle de la formation de la Terre","?"]],"enteteLignes":true},{"id":"flux","type":"graphique","forme":"courbe","titre":"Flux géothermique selon l’âge de la lithosphère océanique","categories":["20","40","60","80","100","120","140","160","180"],"series":[{"nom":"Flux géothermique","valeurs":[106,75,61,53,47,43,40,37,35],"teinte":"corail"}],"axeY":{"titre":"Flux géothermique","unite":"mW/m²","min":0,"max":120,"pas":20},"axeX":{"titre":"Âge de la lithosphère","unite":"millions d’années"},"valeurs":false,"source":"Valeurs arrondies d’un modèle simple de refroidissement"}],"questions":[{"enonce":"Quelle part de la chaleur interne provient de la chaleur résiduelle de la formation de la Terre ?","aide":"Le total fait 100 % : retire la part de la radioactivité.","type":"nombre","unite":"%"},{"enonce":"Touche l’âge de lithosphère pour lequel le flux géothermique est le plus élevé.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"flux","multiple":false},{"enonce":"Quel est le flux géothermique d’une lithosphère âgée de 80 millions d’années ?","aide":"Repère 80 sur l’axe horizontal, puis monte jusqu’à la courbe.","type":"nombre","unite":"mW/m²"},{"enonce":"Comment expliquer la baisse du flux quand l’âge augmente ?","aide":"Pense à ce que devient la lithosphère océanique quand elle s’éloigne de la dorsale.","type":"choix","options":[{"id":"a","texte":"La lithosphère se refroidit et s’épaissit en s’éloignant"},{"id":"b","texte":"Le manteau cesse de convecter sous les océans"},{"id":"c","texte":"La radioactivité disparaît totalement avec le temps"},{"id":"d","texte":"La lithosphère se réchauffe peu à peu en vieillissant"}],"multiple":false},{"enonce":"Classe chaque zone selon son flux géothermique.","aide":"Le flux est fort là où du matériel chaud remonte, faible là où la lithosphère est froide et épaisse.","type":"categories","categories":[{"id":"c0","texte":"Flux élevé"},{"id":"c1","texte":"Flux faible"}],"items":[{"id":"i0","texte":"Une dorsale océanique"},{"id":"i1","texte":"Un vieux bouclier continental"},{"id":"i2","texte":"Un endroit où du matériel chaud remonte"},{"id":"i3","texte":"Une lithosphère océanique âgée"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"100 − 80 = **20 %** : le reste de la chaleur vient de la chaleur résiduelle de l’accrétion et de la différenciation du noyau."},{"cle":{"type":"zone","ids":["k0"]},"explication":"Le flux est maximal pour la lithosphère la plus **jeune** (20 millions d’années), celle qui est proche de la dorsale."},{"cle":{"type":"nombre","valeur":53,"tolerance":2},"affichage":"53 mW/m²","explication":"À 80 millions d’années, le flux est d’environ **53 mW/m²**."},{"cle":{"type":"choix","ids":["a"]},"explication":"En s’éloignant, la lithosphère **se refroidit et s’épaissit** : la conduction y évacue de moins en moins de chaleur."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Le flux est **élevé** aux dorsales, où le matériel chaud remonte, et **faible** sur les vieux boucliers et sous la lithosphère âgée."}]$ex$::jsonb),
  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 3, 3, 15, 50, 4,
