   $ex${"titre":"Les fossiles de Wegener","competence":"lire-carte","situation":"En 1912, le géophysicien Alfred Wegener s’étonne : on retrouve les mêmes fossiles sur des continents aujourd’hui séparés par des milliers de kilomètres d’océan. Il en tire une idée audacieuse.","documents":[{"id":"carte","type":"carte","titre":"Où a-t-on trouvé ces fossiles ?","fond":"monde","cadrage":[-110,-55,170,40],"lieux":[{"id":"z1","lon":-50,"lat":-25,"nom":"Brésil","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lon":22,"lat":-32,"nom":"Afrique du Sud","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lon":-66,"lat":-33,"nom":"Argentine","symbole":"lettre","lettre":"C","teinte":"vert"},{"id":"z4","lon":82,"lat":22,"nom":"Inde","symbole":"lettre","lettre":"D","teinte":"vert"},{"id":"z5","lon":147,"lat":-33,"nom":"Australie","symbole":"lettre","lettre":"E","teinte":"vert"}],"legende":[{"teinte":"corail","texte":"Fossiles de Mesosaurus, petit reptile d’eau douce"},{"teinte":"vert","texte":"Fossiles de Glossopteris, une plante à graines"}],"source":"Sites simplifiés pour l’exercice"}],"questions":[{"enonce":"Touche les deux sites où l’on a trouvé des fossiles de Mesosaurus.","aide":"Cherche, dans la légende, le symbole associé à Mesosaurus.","type":"zone","document":"carte","multiple":true},{"enonce":"Le Mesosaurus vivait dans des eaux douces peu profondes et ne pouvait pas traverser un océan. Que conclut Wegener ?","aide":"Si l’animal ne pouvait pas traverser l’océan, comment se retrouve-t-il des deux côtés ?","type":"choix","options":[{"id":"a","texte":"Les deux sites ne sont pas liés"},{"id":"b","texte":"Les fossiles ont été transportés par les glaciers"},{"id":"c","texte":"Le Mesosaurus nageait très vite"},{"id":"d","texte":"Les continents étaient autrefois réunis"}],"multiple":false},{"enonce":"Relie chaque argument de Wegener à ce qu’il montre.","aide":"Chaque argument a une observation naturelle qui lui correspond.","type":"association","gauche":[{