s se disputent la lumière"},{"id":"g3","texte":"Un renard mange un lapin"}],"droite":[{"id":"d0","texte":"Prédation"},{"id":"d1","texte":"Mutualisme"},{"id":"d2","texte":"Parasitisme"},{"id":"d3","texte":"Compétition"}]}]}$ex$::jsonb,
