  ('7ee89269-3a85-5e93-a2fb-24887dde127b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un samedi en forêt : ce que la nature nous offre","competence":"analyser-document","situation":"Nora et sa famille passent la journée dans une forêt de Bretagne. Tu relèves tout ce que cette forêt leur apporte, sans qu’ils s’en rendent compte.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le journal de Nora","auteur":"Texte écrit pour l’exercice","blocs":["Samedi, nous avons passé la journée en forêt. Papa a ramassé des champignons pour le déjeuner, pendant que mon frère coupait du bois pour le feu du soir.","J’ai respiré l’air frais et admiré le paysage. Les abeilles butinaient les fleurs : sans elles, les pommiers du verger voisin donneraient presque rien. À l’ombre des grands arbres, le sol retient l’eau de pluie et la rivière reste claire."]}],"questions":[{"enonce":"Touche les deux ressources que la famille prélève directement dans la forêt.","aide":"Ce sont des choses qu’on mange ou qu’on brûle.","type":"zone","document":"recit","multiple":true},{"enonce":"Classe ces bénéfices selon la catégorie de service écosystémique.","aide":"On prélève, on régule un phénomène, ou on profite d’un plaisir.","type":"categories","categories":[{"id":"c0","texte":"Approvisionnement"},{"id":"c1","texte":"Régulation"},{"id":"c2","texte":"Culturel"}],"items":[{"id":"i0","texte":"Une rivière dont l’eau est épurée par le sol"},{"id":"i1","texte":"La pollinisation des pommiers par les abeilles"},{"id":"i2","texte":"Les champignons du déjeuner"},{"id":"i3","texte":"Le bois du feu de camp"},{"id":"i4","texte":"Le plaisir d’admirer le paysage"}]},{"enonce":"Que se passerait-il pour le verger voisin si les abeilles disparaissaient ?","aide":"Relis ce que dit Nora des abeilles.","type":"choix","options":[{"id":"a","texte":"Les pommiers produiraient davantage de fruits"},{"id":"b","texte":"Les pommiers produiraient beaucoup moins de fruits"},{"id":"c","texte":"Les pommiers resteraient exactement pareils"},{"id":"d","texte":"Les pommiers seraient pollinisés par la rivière"}],"multiple":false}]}$ex$::jsonb,
