 ou plusieurs gènes et l’environnement.","type":"categories","categories":[{"id":"c0","texte":"Monogénique"},{"id":"c1","texte":"Multifactorielle"}],"items":[{"id":"i0","texte":"Diabète de type 2"},{"id":"i1","texte":"Hémophilie"},{"id":"i2","texte":"Chorée de Huntington"},{"id":"i3","texte":"Hypertension artérielle"},{"id":"i4","texte":"Mucoviscidose"}]}]}$ex$::jsonb,
